ListNode* getIntersectionNode(ListNode* headA, ListNode* headB) {
    // 前提：两条 next 链都有限、无环；不修改连接。
    ListNode* a = headA;
    ListNode* b = headB;
    while (a != b) {
        a = a ? a->next : headB;
        b = b ? b->next : headA;
    }
    return a; // 相交节点，或二者同时成为 nullptr
}

